import csv


def validated_record(record: dict, *, minimum=0):
    amount = int(record['amount'])
    if amount < minimum:
        return None
    if record['note'] == 'skip':
        return None
    return record['kind'], amount


def validated_records(rows):
    for row in rows:
        item = validated_record(row, minimum=0)
        if item is not None:
            yield item


totals = {}
accepted = 0
with open('input.csv', newline='') as source:
    for kind, amount in validated_records(csv.DictReader(source)):
        totals[kind] = totals.get(kind, 0) + amount
        accepted += 1
with open('report.csv', 'w', newline='') as target:
    writer = csv.writer(target, lineterminator='\n')
    writer.writerow(['kind', 'total'])
    for kind in sorted(totals):
        writer.writerow([kind, totals[kind]])
print(accepted)

def words_from_line(line):
    for word in line.lower().split():
        yield word

counts = {}
total = 0
with open('input.txt') as source:
    for line in source:
        for word in words_from_line(line):
            counts[word] = counts.get(word, 0) + 1
            total += 1
with open('report.txt', 'w', newline='') as target:
    for word in sorted(counts):
        target.write(word + '=' + str(counts[word]) + '\n')
print(total)

def record_amount(record:dict)->int:
    return record['amount']

import json

def records_from_lines(source):
    for line in source:
        if line.strip():
            yield json.loads(line)


totals = {}
accepted = 0
with open('input.jsonl') as source:
    for record in records_from_lines(source):
        amount = record_amount(record)
        if amount >= 0:
            kind = record['kind']
            totals[kind] = totals.get(kind, 0) + amount
            accepted += 1
with open('report.json', 'w', newline='') as target:
    json.dump(totals, target, sort_keys=True, ensure_ascii=False, separators=(',', ':'))
    target.write('\n')
print(accepted)

def wanted(line):
    return line.startswith('NEEDLE:')

scanned = 0
match = ''
with open('input.txt') as source:
    for line in source:
        scanned += 1
        if wanted(line):
            match = line
            break
with open('matches.txt', 'w', newline='') as target:
    target.write(match)
print(scanned)
